public interface Shape {                  // contract only: no instance state
    double area();
    default String describe() { return "area " + area(); } // safe growth
    static Shape unitSquare() { return () -> 1.0; }        // SAM from a lambda
}

final class Square implements Shape {
    private final double side;             // state lives in the implementation
    Square(double side) { this.side = side; }
    public double area() { return side * side; }
}

